    public static void main(String[] args) {
        MyLinkedList list = new MyLinkedList();
        list.addLast(1);
        list.addLast(2);
        list.addLast(3);
        list.addFirst(0);
        list.print();
        list.remove(2);
        list.print();
        System.out.println("Contains 3? " + list.contains(3));
    }
